-- 202 preguntas nuevas de la calibración con el examen de 2022, sacadas de los temas oficiales de la Escuela y del TRLHL:
--   tema 5 (31): exenciones del IBI (art. 62), base del ICIO (art. 102) y base, bonificaciones y devolución del IIVTNU (arts. 107–109)
--   tema 18 (26): mangueras y lanzas (Tema_18 V4 de la Escuela), cierra las reservas de 18.2 y 18.5
--   tema 22 (46): ascensores (Tema_22 de la Escuela), incluido el paracaídas instantáneo (0,63 m/s cabina, 1 m/s contrapeso)
--   tema 25 (47): electricidad (Tema_25 V2 de la Escuela)
--   tema 34 (52): IPSIGE (apartado 3 de la versión anterior del TEMA_34 de la Escuela), cubre el nodo 34.6 que estaba vacío
-- Todas las citas son literales del bloque del corpus. Idempotente: no se tocan las que ya existan con el mismo id.
with ins as (
  on conflict (id) do nothing
  returning 1
)
select 'preguntas insertadas: ' || count(*) || ' de 202' as resultado from ins;
